{ config, lib, pkgs, ... }:

let
  cfg = config.v0id.entireioTools;

  # Use Go 1.26.4 from unstable to satisfy entire.io/auth-go requirements
  go1264 = (import <nixpkgs-unstable> { system = pkgs.system; }).go;

  # ---------------------------------------------------------------------------
  # entireio/cli — Go; produces 'entire' and 'git-remote-entire' binaries
  # https://github.com/entireio/cli
  # ---------------------------------------------------------------------------
  entire = pkgs.buildGoModule {
    pname = "entire";
    version = "unstable-2026-06-03";

    src = pkgs.fetchFromGitHub {
      owner = "entireio";
      repo = "cli";
      rev = "1db011c007fe0c82d60a0d497da416da702906c7";
      hash = "sha256-ey/REDACTED";
    };

    vendorHash = lib.fakeHash;

    # Override with Go 1.26.4 from unstable
    go = go1264;

    subPackages = [
      "cmd/entire"
      "cmd/git-remote-entire"
    ];

    meta = with lib; {
      description = "Entire CLI — orchestrate AI coding agents across repos";
      homepage = "https://github.com/entireio/cli";
      license = licenses.mit;
      mainProgram = "entire";
    };
  };

  # ---------------------------------------------------------------------------
  # entireio/entire-run — Go; 'entire-run' plugin binary for the Entire CLI
  # https://github.com/entireio/entire-run
  # ---------------------------------------------------------------------------
  entireRun = pkgs.buildGoModule {
    pname = "entire-run";
    version = "unstable-2026-06-03";

    src = pkgs.fetchFromGitHub {
      owner = "entireio";
      repo = "entire-run";
      rev = "917cc3002c9e58e61c7494424f60bb2d5e96da2c";
      hash = "REDACTED";
    };

    vendorHash = "REDACTED";

    # Override with Go 1.26.4 from unstable
    go = go1264;

    # The main package lives under cmd/; adjust if 'go build ./...' resolves differently.
    subPackages = [ "cmd" ];

    meta = with lib; {
      description = "Entire-run plugin — parallel agent execution for the Entire CLI";
      homepage = "https://github.com/entireio/entire-run";
      license = licenses.mit;
      mainProgram = "entire-run";
    };
  };

  # ---------------------------------------------------------------------------
  # entireio/git-sync — Go; lightweight git-sync tool
  # https://github.com/entireio/git-sync
  # ---------------------------------------------------------------------------
  gitSync = pkgs.buildGoModule {
    pname = "git-sync";
    version = "unstable-2026-06-03";

    src = pkgs.fetchFromGitHub {
      owner = "entireio";
      repo = "git-sync";
      rev = "db440e18435283c0ac9ba966a21d1594654dc9b3";
      hash = "REDACTED";
    };

    vendorHash = "REDACTED";

    # Override with Go 1.26.4 from unstable
    go = go1264;

    subPackages = [ "cmd/git-sync" ];

    meta = with lib; {
      description = "Git sync tool from Entire.io (in-memory go-git backend)";
      homepage = "https://github.com/entireio/git-sync";
      license = licenses.mit;
      mainProgram = "git-sync";
    };
  };
in
{
  options.v0id.entireioTools = {
    enable = lib.mkEnableOption "Entire.io CLI tools";
  };

  config = lib.mkIf cfg.enable {
    environment.systemPackages = [
      entire
      entireRun
      gitSync
    ];
  };
}

