    println!(
        "Skills are selectable analytical lenses (a-la-carte) — invoke only the steps your workflow needs.\n"
    );
    println!("{:<20} {:>7}  {:>12}", "SKILL", "VERSION", "TOKENS (~)");
    println!("{}", "-".repeat(44));
    for (name, content, version) in SKILLS {
